"use client";

import { useEffect, useRef, useState } from "react";
import "swagger-ui-dist/swagger-ui.css";
import "./swagger-theme.css";

/** Same-origin copy of backend/api/openapi.yaml, generated by pnpm generate:api. */
export const specUrl = "/openapi.json";

export function SwaggerReference() {
  const host = useRef<HTMLDivElement>(null);
  const [state, setState] = useState<"loading" | "ready" | "failed">("loading");

  useEffect(() => {
    const node = host.current;
    if (!node) return;
    let cancelled = false;
    // Swagger UI touches window and document, so it only loads in the browser.
    import("swagger-ui-dist/swagger-ui-es-bundle.js")
      .then(({ default: SwaggerUIBundle }) => {
        if (cancelled) return;
        SwaggerUIBundle({
          url: specUrl,
          domNode: node,
          deepLinking: false,
          persistAuthorization: false,
          docExpansion: "list",
          defaultModelsExpandDepth: -1,
          onComplete: () => {
            // Swagger UI renders its own <main>. Inside the dashboard shell
            // that would be a second main landmark, which confuses screen
            // readers, so give it a labelled region role instead.
            node.querySelectorAll("main").forEach((element) => {
              element.setAttribute("role", "region");
              element.setAttribute("aria-label", "API operations");
            });
          },
          requestInterceptor: (request) => {
            request.credentials = "same-origin";
            return request;
          },
        });
        setState("ready");
      })
      .catch(() => {
        if (!cancelled) setState("failed");
      });
    return () => {
      cancelled = true;
      node.replaceChildren();
    };
  }, []);

  return (
    <>
      {state === "loading" ? (
        <p role="status" className="swagger-status">
          Loading the API reference...
        </p>
      ) : null}
      {state === "failed" ? (
        <p role="alert" className="swagger-status">
          The interactive reference could not load. The OpenAPI document is
          available at <a href={specUrl}>{specUrl}</a>.
        </p>
      ) : null}
      <div
        ref={host}
        className="swagger-surface"
        data-testid="swagger-host"
        aria-busy={state === "loading"}
      />
    </>
  );
}
